"""The chart of accounts: validated paths, a tree of accounts and chart patterns."""

import datetime
import re

from tallybook.currency import CURRENCIES
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Account

ROOT_TYPES = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}
TYPES = tuple(ROOT_TYPES.values())

_SEGMENT = re.compile(r"[A-Z][A-Za-z0-9_-]*")


class ChartError(ValidationError):
    """A chart operation was refused (a duplicate has code ``conflict``)."""


def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def valid_path(text):
    """True when ``text`` is a well-formed account path; never raises."""
    if not isinstance(text, str):
        return False
    segments = text.split(":")
    if segments[0] not in ROOT_TYPES:
        return False
    return all(_SEGMENT.fullmatch(segment) for segment in segments)


def _require_path(path):
    if not valid_path(path):
        raise ChartError("invalid account path: %r" % (path,))


def parent_path(path):
    """The path without its last segment, or None for a root account."""
    _require_path(path)
    head, sep, _ = path.rpartition(":")
    return head if sep else None


def account_type(path):
    """The account type (``asset``, ``liability``...) given by the root segment."""
    _require_path(path)
    return ROOT_TYPES[path.split(":", 1)[0]]


def _sort_key(path):
    return path.split(":")


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern: %r" % (pattern,))
    segments = pattern.split(":")
    for segment in segments:
        if segment not in ("*", "**") and not _SEGMENT.fullmatch(segment):
            raise ChartError("invalid account pattern: %r" % (pattern,))
    return segments


def _match_wildcards(pattern, segments):
    reach = {0}
    count = len(segments)
    for part in pattern:
        following = set()
        for pos in reach:
            if part == "**":
                following.update(range(pos + 1, count + 1))
            elif pos < count and (part == "*" or part == segments[pos]):
                following.add(pos + 1)
        reach = following
        if not reach:
            return False
    return count in reach


def path_matches(pattern, path):
    """Chart-dialect pattern match of one path (see the Accounts section)."""
    parts = _check_pattern(pattern)
    if not isinstance(path, str):
        return False
    segments = path.split(":")
    if "*" in parts or "**" in parts:
        return _match_wildcards(parts, segments)
    return segments[:len(parts)] == parts


class Chart:
    """A set of accounts forming a tree. Parents are created as needed."""

    def __init__(self):
        self._accounts = {}
        self._declared = set()
        self._sorted = None

    def add(self, path, type=None, currency=None, opened=None, note=""):
        _require_path(path)
        root_type = ROOT_TYPES[path.split(":", 1)[0]]
        if type is None:
            type = root_type
        elif not isinstance(type, str) or type not in TYPES:
            raise ChartError("unknown account type: %r" % (type,))
        elif type != root_type:
            raise ChartError("account %s is of type %s, not %s" % (path, root_type, type))
        if currency is not None and (not isinstance(currency, str) or currency not in CURRENCIES):
            raise ChartError("unknown currency: %r" % (currency,))
        if opened is not None and not _is_date(opened):
            raise ChartError("opened must be a date, not %r" % (opened,))
        if not isinstance(note, str):
            raise ChartError("note must be text, not %r" % (note,))
        if path in self._declared:
            raise ChartError("account %s already exists" % path, code="conflict")
        account = self._accounts.get(path)
        if account is None:
            account = Account(path, type, currency, opened, None, note)
            self._accounts[path] = account
            parent = parent_path(path)
            while parent is not None and parent not in self._accounts:
                self._accounts[parent] = Account(parent, ROOT_TYPES[parent.split(":", 1)[0]])
                parent = parent_path(parent)
        else:
            account.currency = currency
            account.opened = opened
            account.note = note
        self._declared.add(path)
        self._sorted = None
        return account

    def get(self, path):
        if not isinstance(path, str) or path not in self._accounts:
            raise NotFoundError("no such account: %s" % (path,))
        return self._accounts[path]

    def exists(self, path):
        return isinstance(path, str) and path in self._accounts

    def __contains__(self, path):
        return self.exists(path)

    def accounts(self):
        if self._sorted is None:
            self._sorted = sorted(self._accounts.values(), key=lambda a: _sort_key(a.path))
        return list(self._sorted)

    def descendants(self, path):
        self.get(path)
        prefix = path + ":"
        return [a for a in self.accounts() if a.path.startswith(prefix)]

    def children(self, path):
        depth = len(path.split(":")) + 1 if self.exists(path) else 0
        return [a for a in self.descendants(path) if len(a.path.split(":")) == depth]

    def is_leaf(self, path):
        return not self.descendants(path)

    def is_open(self, path, on):
        account = self.get(path)
        if not _is_date(on):
            raise ChartError("not a date: %r" % (on,))
        return ((account.opened is None or account.opened <= on)
                and (account.closed is None or on <= account.closed))

    def close(self, path, on):
        account = self.get(path)
        if not _is_date(on):
            raise ChartError("not a date: %r" % (on,))
        if account.closed is not None:
            raise ChartError("account %s is already closed" % path)
        if account.opened is not None and on < account.opened:
            raise ChartError("account %s cannot be closed on %s, before it opened on %s"
                             % (path, on.isoformat(), account.opened.isoformat()))
        account.closed = on
        return account

    def matches(self, pattern):
        _check_pattern(pattern)
        return [a for a in self.accounts() if path_matches(pattern, a.path)]

