"""The ledger: validated transactions and the balances worked out from them."""

import datetime
import re

from tallybook.accounts import Chart
from tallybook.currency import RateTable
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Posting, Transaction
from tallybook.money import Money, format_minor

_TAG = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


class LedgerError(ValidationError):
    """A transaction (or a ledger call) was refused."""


def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _is_line(value):
    return isinstance(value, str) and "\n" not in value and "\r" not in value


def _check_as_of(as_of):
    if as_of is not None and not _is_date(as_of):
        raise LedgerError("as_of must be a date, not %r" % (as_of,))


class Ledger:
    """Transactions plus the chart and rate table they are judged against."""

    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._next_id = 1
        self._sorted = None

    def __len__(self):
        return len(self._txs)

    def _prepare(self, tx, replace_id=None):
        """Validate ``tx`` and return ``(stored, next_id)`` without changing anything."""
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: %r" % (tx,))
        if not _is_date(tx.date):
            raise LedgerError("transaction date must be a date, not %r" % (tx.date,))
        if not isinstance(tx.flag, str) or tx.flag not in ("*", "!"):
            raise LedgerError("flag must be '*' or '!', not %r" % (tx.flag,))
        for label, value in (("payee", tx.payee), ("narration", tx.narration)):
            if not _is_line(value):
                raise LedgerError("%s must be text without a line break" % label)
        if isinstance(tx.tags, (str, bytes)) or not hasattr(tx.tags, "__iter__"):
            raise LedgerError("tags must be a collection of text")
        for tag in tx.tags:
            if not isinstance(tag, str) or not _TAG.fullmatch(tag):
                raise LedgerError("invalid tag: %r" % (tag,))
        tags = tuple(sorted(set(tx.tags)))
        if not isinstance(tx.postings, (list, tuple)):
            raise LedgerError("postings must be a list")
        postings = list(tx.postings)
        for posting in postings:
            if not isinstance(posting, Posting):
                raise LedgerError("not a posting: %r" % (posting,))
            if not _is_line(posting.note):
                raise LedgerError("a posting note must be text without a line break")
            if posting.amount is not None and not isinstance(posting.amount, Money):
                raise LedgerError("a posting amount must be Money or None, not %r" % (posting.amount,))
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        for posting in postings:
            self._check_account(posting, tx.date)

        sums = {}
        missing = []
        for index, posting in enumerate(postings):
            if posting.amount is None:
                missing.append(index)
            else:
                currency = posting.amount.currency
                sums[currency] = sums.get(currency, 0) + posting.amount.minor
        off = {cur: total for cur, total in sums.items() if total != 0}
        if len(missing) > 1:
            raise LedgerError("more than one posting without an amount")
        if missing:
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            index = missing[0]
            blank = postings[index]
            filled = [Posting(blank.account, Money(-off[cur], cur), blank.note) for cur in sorted(off)]
            for posting in filled:
                self._check_account(posting, tx.date)
            postings[index:index + 1] = filled
        elif off:
            detail = ", ".join("%s %s" % (cur, format_minor(off[cur], cur)) for cur in sorted(off))
            raise LedgerError("transaction does not balance: %s" % detail)

        if replace_id is not None:
            new_id = replace_id
        elif tx.id is None:
            new_id = self._next_id
        else:
            if type(tx.id) is not int or tx.id < 1:
                raise LedgerError("transaction id must be a whole number of at least 1, not %r" % (tx.id,))
            if tx.id in self._txs:
                raise LedgerError("transaction id %d already exists" % tx.id)
            new_id = tx.id
        stored = Transaction(tx.date, tx.payee, tx.narration, postings, tags, tx.flag, new_id)
        return stored, max(self._next_id, new_id + 1)

    def _check_account(self, posting, on):
        path = posting.account
        if not self.chart.exists(path):
            raise LedgerError("unknown account %s" % (path,))
        if not self.chart.is_open(path, on):
            raise LedgerError("account %s is not open on %s" % (path, on.isoformat()))
        held = self.chart.get(path).currency
        if held is not None and posting.amount is not None and posting.amount.currency != held:
            raise LedgerError("account %s only holds %s, not %s" % (path, held, posting.amount.currency))

    def _commit(self, stored, next_id):
        self._txs[stored.id] = stored
        self._next_id = next_id
        self._sorted = None

    def add(self, tx):
        stored, next_id = self._prepare(tx)
        self._commit(stored, next_id)
        return stored

    def add_many(self, transactions):
        saved_next = self._next_id
        added = []
        try:
            for tx in transactions:
                stored, next_id = self._prepare(tx)
                self._commit(stored, next_id)
                added.append(stored)
        except BaseException:
            for stored in added:
                del self._txs[stored.id]
            self._next_id = saved_next
            self._sorted = None
            raise
        return added

    def replace(self, id, tx):
        self.get(id)
        if isinstance(tx, Transaction) and tx.id is not None and tx.id != id:
            raise LedgerError("transaction id %r does not match %r" % (tx.id, id))
        stored, next_id = self._prepare(tx, replace_id=id)
        self._commit(stored, next_id)
        return stored

    def get(self, id):
        if type(id) is not int or id not in self._txs:
            raise NotFoundError("no transaction with id %s" % (id,))
        return self._txs[id]

    def remove(self, id):
        tx = self.get(id)
        del self._txs[id]
