"""The text journal: a whole book as one readable file."""

import re
from dataclasses import dataclass, field
from typing import List

from tallybook.accounts import account_type, valid_path
from tallybook.currency import currency as lookup_currency
from tallybook.dates import format_date, parse_date
from tallybook.errors import ParseError, TallybookError
from tallybook.ledger import Ledger
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money

_TAG = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_RATE = re.compile(r"[0-9]+(\.[0-9]{1,8})?")
_BLANKS = " \t"


class JournalError(ParseError):
    """A mistake in journal text; ``line`` is the 1-based line of the first one."""

    def __init__(self, line, description):
        super().__init__("line %s: %s" % (line, description))
        self.line = line


@dataclass
class Journal:
    accounts: List[Account] = field(default_factory=list)
    rates: List[tuple] = field(default_factory=list)
    transactions: List[Transaction] = field(default_factory=list)

    def to_ledger(self):
        """A new Ledger holding this journal; book-keeping errors come out unchanged."""
        ledger = Ledger()
        for account in self.accounts:
            ledger.chart.add(account.path, account.type, account.currency, account.opened, account.note)
            if account.closed is not None:
                ledger.chart.close(account.path, account.closed)
        for src, dst, on, rate_text in self.rates:
            ledger.rates.set(src, dst, rate_text, on)
        for tx in self.transactions:
            ledger.add(tx)
        return ledger


def _scan(line, number):
    """Split a line into ``(tokens, comment)``; a token is ``("w", word)`` or ``("s", string)``."""
    tokens = []
    comment = None
    pos, size = 0, len(line)
    while pos < size:
        char = line[pos]
        if char in _BLANKS:
            pos += 1
        elif char == ";":
            comment = line[pos + 1:].strip(_BLANKS)
            break
        elif char == '"':
            pos += 1
            chars = []
            while True:
                if pos >= size:
                    raise JournalError(number, "unterminated quoted string")
                char = line[pos]
                if char == '"':
                    pos += 1
                    break
                if char == "\\":
                    if pos + 1 >= size or line[pos + 1] not in '"\\':
                        raise JournalError(number, "bad escape in quoted string")
                    chars.append(line[pos + 1])
                    pos += 2
                else:
                    chars.append(char)
                    pos += 1
            if pos < size and line[pos] not in _BLANKS and line[pos] != ";":
                raise JournalError(number, "text right after a closing quote")
            tokens.append(("s", "".join(chars)))
        else:
            start = pos
            while pos < size and line[pos] not in _BLANKS and line[pos] not in ';"':
                pos += 1
            if pos < size and line[pos] == '"':
                raise JournalError(number, "unexpected quote")
            tokens.append(("w", line[start:pos]))
    return tokens, comment


def _wrap(number, call, *args):
    try:
        return call(*args)
    except JournalError:
        raise
    except TallybookError as error:
        raise JournalError(number, error.message) from None


def _date(number, text):
    return _wrap(number, parse_date, text)


def _currency(number, code):
    return _wrap(number, lookup_currency, code).code


def _words(number, tokens, what):
    for kind, value in tokens:
        if kind != "w":
            raise JournalError(number, "unexpected quoted string in %s" % what)
    return [value for _, value in tokens]


def _parse_account(number, tokens, seen):
    if len(tokens) < 2 or tokens[1][0] != "w":
        raise JournalError(number, "account line needs an account path")
    path = tokens[1][1]
    if not valid_path(path):
        raise JournalError(number, "invalid account path: %s" % path)
    if path in seen:
        raise JournalError(number, "account %s is already declared" % path)
    rest = tokens[2:]
    cur = opened = closed = None
    note = ""
    if rest and rest[0][0] == "w" and rest[0][1] not in ("open", "close"):
        cur = _currency(number, rest[0][1])
        rest = rest[1:]
    if len(rest) >= 2 and rest[0] == ("w", "open") and rest[1][0] == "w":
        opened = _date(number, rest[1][1])
        rest = rest[2:]
    if len(rest) >= 2 and rest[0] == ("w", "close") and rest[1][0] == "w":
        closed = _date(number, rest[1][1])
        rest = rest[2:]
    if rest and rest[0][0] == "s":
        note = rest[0][1]
        rest = rest[1:]
    if rest:
        raise JournalError(number, "unexpected %r in account line" % rest[0][1])
    if opened is not None and closed is not None and closed < opened:
        raise JournalError(number, "account %s closes before it opens" % path)
    seen.add(path)
    return Account(path, account_type(path), cur, opened, closed, note)


def _parse_rate(number, tokens):
    words = _words(number, tokens, "rate line")
    if len(words) != 5:
        raise JournalError(number, "rate line must be: rate DATE FROM TO RATE")
    _, date_text, src, dst, rate_text = words
    on = _date(number, date_text)
    src, dst = _currency(number, src), _currency(number, dst)
    if src == dst:
