        else:
            row = "  %s  %s %s" % (posting.account.ljust(name_width),
                                   posting.amount.amount_str().rjust(amount_width),
                                   posting.amount.currency)
        note = posting.note.strip(_BLANKS)
        if note:
            row += "  ; " + note
        lines.append(row)
    return "\n".join(lines) + "\n"


def _format_account(account):
    row = "account " + account.path
    if account.currency:
        row += " " + account.currency
    if account.opened is not None:
        row += " open " + format_date(account.opened)
    if account.closed is not None:
        row += " close " + format_date(account.closed)
    if account.note:
        row += " " + _quote(account.note)
    return row


def format_journal(journal):
    """The canonical text of a journal (accounts, rates, then transactions)."""
    blocks = []
    if journal.accounts:
        blocks.append("".join(_format_account(a) + "\n" for a in journal.accounts))
    if journal.rates:
        blocks.append("".join("rate %s %s %s %s\n" % (format_date(on), src, dst, text)
                              for src, dst, on, text in journal.rates))
    blocks.extend(format_transaction(tx) for tx in journal.transactions)
    return "\n".join(blocks)
